<?php
namespace Tests\Feature;
use App\Models\Ingredient;use App\Models\InventoryBatch;use App\Models\Unit;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Laravel\Sanctum\Sanctum;use Tests\TestCase;
class ProductionFlowTest extends TestCase {use RefreshDatabase;
 public function test_production_consumes_inputs_and_creates_dough_batch():void{$this->seed();$user=User::first();Sanctum::actingAs($user);$g=Unit::where('symbol','g')->first();$flour=Ingredient::create(['branch_id'=>$user->branch_id,'base_unit_id'=>$g->id,'name'=>'Harina']);$dough=Ingredient::create(['branch_id'=>$user->branch_id,'base_unit_id'=>$g->id,'name'=>'Masa base']);InventoryBatch::create(['branch_id'=>$user->branch_id,'ingredient_id'=>$flour->id,'received_at'=>today(),'initial_quantity'=>5000,'available_quantity'=>5000]);$recipe=$this->postJson('/api/production-recipes',['name'=>'Masa base','yield_quantity'=>1000,'yield_unit_id'=>$g->id,'shelf_life_days'=>1,'items'=>[['ingredient_id'=>$flour->id,'quantity'=>600]]])->assertCreated()->json();$this->postJson('/api/production-batches',['production_recipe_id'=>$recipe['id'],'output_ingredient_id'=>$dough->id,'multiplier'=>2])->assertCreated();$this->assertEquals(3800,$flour->batches()->sum('available_quantity'));$this->assertEquals(2000,$dough->batches()->sum('available_quantity'));}
 public function test_failed_production_rolls_back_all_inputs():void{$this->seed();$u=User::first();Sanctum::actingAs($u);$g=Unit::where('symbol','g')->first();$a=Ingredient::create(['branch_id'=>$u->branch_id,'base_unit_id'=>$g->id,'name'=>'Harina']);$b=Ingredient::create(['branch_id'=>$u->branch_id,'base_unit_id'=>$g->id,'name'=>'Levadura']);$out=Ingredient::create(['branch_id'=>$u->branch_id,'base_unit_id'=>$g->id,'name'=>'Masa']);InventoryBatch::create(['branch_id'=>$u->branch_id,'ingredient_id'=>$a->id,'received_at'=>today(),'initial_quantity'=>1000,'available_quantity'=>1000]);$recipe=$this->postJson('/api/production-recipes',['name'=>'Masa','yield_quantity'=>1000,'yield_unit_id'=>$g->id,'shelf_life_days'=>1,'items'=>[['ingredient_id'=>$a->id,'quantity'=>600],['ingredient_id'=>$b->id,'quantity'=>10]]])->json();$this->postJson('/api/production-batches',['production_recipe_id'=>$recipe['id'],'output_ingredient_id'=>$out->id,'multiplier'=>1])->assertUnprocessable();$this->assertEquals(1000,$a->batches()->sum('available_quantity'));$this->assertDatabaseCount('production_batches',0);}
}
